         hasWater = hasWater || adjacentBlockState.is(Blocks.FROSTED_ICE) || adjacentFluidState.is(net.minecraft.tags.FluidTags.WATER);
         if (hasWater)
            break; //No point continuing.
      }
      return isBeach && hasWater;
   }
   return false;
